def shell(title,description,body,depth=0):
    p='../'*depth
    return f'''<!doctype html><html lang="es-CL"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{escape(title)} | Sercot</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="#357c70"><link rel="stylesheet" href="{p}assets/style.css?v=12"><script src="{p}assets/app.js?v=12" defer></script></head><body>
<a class="skip" href="#contenido">Saltar al contenido</a><div class="preview">Propuesta de diseño · Vista previa privada</div>
<header><a class="brand" href="{p}index.html" aria-label="Sercot, inicio"><span class="brand-dots" aria-hidden="true"><i></i><i></i><i></i></span><strong>SERCOT<span>SPA</span></strong><small>CONTABLES Y TRIBUTARIOS</small></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menú <span>☰</span></button><nav id="navigation" aria-label="Navegación principal"><a href="{p}servicios/index.html">Servicios</a><a href="{p}nosotros.html">Nosotros</a><a href="{p}index.html#como-trabajamos">Cómo trabajamos</a><a class="button small" href="{p}contacto.html">Conversemos <span aria-hidden="true">↗</span></a></nav></header>
<main id="contenido">{body}</main><footer><div><span class="footer-brand">SERCOT</span><p>Claridad para tu negocio.<br>Respaldo para tus decisiones.</p></div><div><h2>Explora</h2><a href="{p}servicios/index.html">Nuestros servicios</a><a href="{p}nosotros.html">Conoce Sercot</a><a href="{p}contacto.html">Orientar mi consulta</a></div><div><h2>Contables y tributarios</h2><p>Una atención cercana.<br>Una mirada a tu situación.</p></div><div class="footer-bottom">Sercot SPA <span>Propuesta de contenidos y diseño · Septiembre 2026</span></div></footer></body></html>'''

def cards(prefix='',limit=None,indices=None):
    return ''.join(f'<a class="service-card" href="{prefix}{s["slug"]}.html"><span class="card-num">{i+1:02d} <span>↗</span></span><h3>{s["name"]}</h3><p>{s["desc"]}</p><span class="card-link">Conocer el servicio <span>→</span></span></a>' for i,s in enumerate(services[:limit]) if indices is None or i in indices)

